                        {/* ΓòÉΓòÉΓòÉ Bottom trust strip ΓòÉΓòÉΓòÉ */}
                        <div className="px-12 pb-10">
                            <div className="flex items-center justify-center gap-5 text-xs text-forest-muted/40 uppercase tracking-wider">
