            )}
        </AnimatePresence>
    );
}

import { useState, useEffect } from 'react';
import { alertAPI } from '../services/api';
import { Bell, Plus, Trash2, X, AlertTriangle, CheckCircle, ToggleLeft, ToggleRight, TreePine, Leaf, Shield } from 'lucide-react';

export default function Alerts() {
    const [rules, setRules] = useState([]);
    const [alerts, setAlerts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showCreate, setShowCreate] = useState(false);
    const [error, setError] = useState('');
    const [tab, setTab] = useState('rules');
    const [form, setForm] = useState({ name: '', metric: '', operator: '>', threshold: '', severity: 'MEDIUM' });

    useEffect(() => { fetchData(); }, []);

    const fetchData = async () => {
        try {
            const [rRes, aRes] = await Promise.allSettled([
                alertAPI.getRules(),
                alertAPI.getAlerts(50),
            ]);
            if (rRes.status === 'fulfilled') setRules(rRes.value.data || []);
            if (aRes.status === 'fulfilled') setAlerts(aRes.value.data.alerts || []);
        } catch { } finally { setLoading(false); }
    };

    const handleCreateRule = async (e) => {
        e.preventDefault();
        try {
            await alertAPI.createRule({ ...form, threshold: parseFloat(form.threshold) });
            setShowCreate(false);
            setForm({ name: '', metric: '', operator: '>', threshold: '', severity: 'MEDIUM' });
            fetchData();
        } catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    const handleDeleteRule = async (id) => {
        if (!confirm('Delete this rule?')) return;
        try { await alertAPI.deleteRule(id); fetchData(); }
        catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    const handleToggle = async (rule) => {
        try {
            await alertAPI.updateRule(rule.id, { ...rule, enabled: !rule.enabled });
            fetchData();
        } catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    const handleAck = async (id) => {
        try { await alertAPI.acknowledge(id); fetchData(); }
        catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    const sevColors = {
        CRITICAL: { bg: 'bg-red-500/8', border: 'border-red-500/15', text: 'text-red-400', icon: '≡ƒö┤', glow: 'rgba(239, 68, 68, 0.05)' },
        HIGH: { bg: 'bg-amber-500/8', border: 'border-amber-500/15', text: 'text-amber-400', icon: '≡ƒƒí', glow: 'rgba(245, 158, 11, 0.05)' },
        MEDIUM: { bg: 'bg-forest-gold/8', border: 'border-forest-gold/15', text: 'text-forest-gold', icon: '≡ƒƒá', glow: 'rgba(230, 180, 34, 0.05)' },
        LOW: { bg: 'bg-forest-spring/8', border: 'border-forest-spring/15', text: 'text-forest-spring', icon: '≡ƒƒó', glow: 'rgba(82, 183, 136, 0.05)' },
    };

    if (loading) return (
        <div className="flex items-center justify-center h-[50vh]">
            <div className="relative">
                <div className="animate-spin rounded-full h-14 w-14 border-t-2 border-b-2 border-forest-spring"></div>
                <TreePine className="w-6 h-6 text-forest-spring absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
        </div>
    );

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-forest-cream font-display flex items-center gap-3">
                        <Bell className="w-7 h-7 text-amber-400" />
                        Alerts
                    </h1>
                    <p className="text-sm text-forest-muted mt-1.5">Configure alert rules and monitor triggered alerts</p>
                </div>
                <button onClick={() => setShowCreate(true)} className="btn-primary flex items-center gap-2 text-sm">
                    <Plus className="w-4 h-4" /> New Rule
                </button>
            </div>

            {error && (
                <div className="bg-red-500/10 border border-red-500/20 text-red-400 px-4 py-3 rounded-xl text-sm flex justify-between items-center">
                    <span>{error}</span>
                    <button onClick={() => setError('')}><X className="w-4 h-4" /></button>
                </div>
            )}

            {/* Tabs */}
            <div className="flex items-center gap-6 border-b border-forest-border/20 pb-1">
                <button onClick={() => setTab('rules')}
                    className={`flex items-center gap-2 pb-3 px-1 text-sm font-medium border-b-2 transition-all ${tab === 'rules'
                        ? 'text-emerald-400 border-emerald-400'
                        : 'text-forest-muted border-transparent hover:text-forest-cream'}`}>
                    <Shield className="w-4 h-4" /> Rules
                    <span className="ml-1.5 text-[10px] bg-forest-card/30 px-2 py-0.5 rounded-full text-forest-muted/60">{rules.length}</span>
                </button>
                <button onClick={() => setTab('alerts')}
                    className={`flex items-center gap-2 pb-3 px-1 text-sm font-medium border-b-2 transition-all ${tab === 'alerts'
                        ? 'text-amber-400 border-amber-400'
                        : 'text-forest-muted border-transparent hover:text-forest-cream'}`}>
                    <AlertTriangle className="w-4 h-4" /> Triggered
                    <span className="ml-1.5 text-[10px] bg-forest-card/30 px-2 py-0.5 rounded-full text-forest-muted/60">{alerts.length}</span>
                </button>
            </div>

            {tab === 'rules' ? (
                <div className="space-y-3">
                    {rules.length === 0 ? (
                        <div className="glass-panel rounded-2xl p-16 text-center">
                            <span className="text-6xl block mb-4">≡ƒöö</span>
                            <h3 className="text-xl font-semibold text-forest-cream font-display mb-2">No Alert Rules</h3>
                            <p className="text-forest-muted text-sm">Create your first alert rule to monitor farm conditions.</p>
                        </div>
                    ) : (
                        rules.map(rule => {
                            const sev = sevColors[rule.severity] || sevColors.MEDIUM;
                            return (
                                <div key={rule.id} className={`glass-card rounded-2xl p-5 flex items-center gap-4 ${!rule.enabled ? 'opacity-50' : ''}`}>
                                    <div className="flex-1">
                                        <div className="flex items-center gap-3">
                                            <h3 className="font-semibold text-forest-cream">{rule.name}</h3>
                                            <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${sev.bg} ${sev.text} border ${sev.border}`}>
                                                {rule.severity}
                                            </span>
                                        </div>
                                        <p className="text-xs text-forest-muted mt-1.5 font-mono">
                                            {rule.metric} {rule.operator} {rule.threshold}
                                        </p>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button onClick={() => handleToggle(rule)}
                                            className="text-forest-muted hover:text-forest-cream transition-colors p-1.5 rounded-lg hover:bg-forest-card/30">
                                            {rule.enabled ? <ToggleRight className="w-6 h-6 text-emerald-400" /> : <ToggleLeft className="w-6 h-6" />}
                                        </button>
                                        <button onClick={() => handleDeleteRule(rule.id)}
                                            className="text-forest-muted hover:text-red-400 transition-colors p-1.5 rounded-lg hover:bg-red-500/[0.06]">
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>
            ) : (
                <div className="space-y-3">
                    {alerts.length === 0 ? (
                        <div className="glass-panel rounded-2xl p-16 text-center">
                            <span className="text-6xl block mb-4">≡ƒî┐</span>
                            <h3 className="text-xl font-semibold text-forest-cream font-display mb-2">All Clear</h3>
                            <p className="text-forest-muted text-sm">No alerts have been triggered. The forest is at peace.</p>
                        </div>
                    ) : (
                        alerts.map((a, i) => {
                            const sev = sevColors[a.severity] || sevColors.MEDIUM;
                            return (
                                <div key={i} className={`p-5 rounded-2xl ${sev.bg} border ${sev.border} transition-all hover:scale-[1.005]`}
                                    style={{ boxShadow: `0 4px 20px ${sev.glow}` }}>
                                    <div className="flex items-center justify-between mb-2">
                                        <div className="flex items-center gap-2">
                                            <span className="text-sm">{sev.icon}</span>
                                            <span className={`text-xs font-bold uppercase tracking-wider ${sev.text}`}>{a.severity}</span>
                                        </div>
                                        <span className="text-[11px] text-forest-muted/40">{new Date(a.triggered_at).toLocaleString()}</span>
                                    </div>
                                    <p className="text-sm text-forest-cream mb-3">{a.message}</p>
                                    {!a.acknowledged && (
                                        <button onClick={() => handleAck(a.id)}
                                            className="flex items-center gap-1.5 text-xs text-forest-spring hover:text-forest-accent transition-colors font-medium">
                                            <CheckCircle className="w-3.5 h-3.5" /> Acknowledge
                                        </button>
                                    )}
                                </div>
                            );
                        })
                    )}
                </div>
            )}

            {/* Create Rule Modal */}
            {showCreate && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-forest-darkest/85 backdrop-blur-md" onClick={() => setShowCreate(false)}>
                    <div className="rounded-3xl p-8 max-w-lg w-full border border-forest-border/25 page-enter"
                        style={{
                            background: 'linear-gradient(135deg, rgba(19, 42, 19, 0.97), rgba(10, 23, 10, 0.99))',
                            boxShadow: '0 30px 100px rgba(0,0,0,0.6), 0 0 60px rgba(74, 222, 128, 0.04)',
                        }}
                        onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-xl font-bold text-forest-cream font-display flex items-center gap-2">
                                <Leaf className="w-5 h-5 text-forest-spring" /> New Alert Rule
                            </h2>
                            <button onClick={() => setShowCreate(false)} className="text-forest-muted hover:text-forest-cream p-1"><X className="w-5 h-5" /></button>
                        </div>
                        <form onSubmit={handleCreateRule} className="space-y-4">
                            <div>
                                <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Rule Name</label>
                                <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="input-scada w-full" required placeholder="e.g. High Temperature Alert" />
                            </div>
                            <div className="grid grid-cols-3 gap-3">
                                <div>
                                    <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Metric</label>
                                    <input value={form.metric} onChange={(e) => setForm({ ...form, metric: e.target.value })} className="input-scada w-full" required placeholder="temperature" />
                                </div>
                                <div>
                                    <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Operator</label>
                                    <select value={form.operator} onChange={(e) => setForm({ ...form, operator: e.target.value })} className="input-scada w-full">
                                        <option value=">">&gt;</option>
                                        <option value="<">&lt;</option>
                                        <option value=">=">&gt;=</option>
                                        <option value="<=">&lt;=</option>
                                        <option value="==">=</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Threshold</label>
                                    <input type="number" step="0.01" value={form.threshold} onChange={(e) => setForm({ ...form, threshold: e.target.value })} className="input-scada w-full" required />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Severity</label>
                                <select value={form.severity} onChange={(e) => setForm({ ...form, severity: e.target.value })} className="input-scada w-full">
                                    <option value="LOW">Low</option>
                                    <option value="MEDIUM">Medium</option>
                                    <option value="HIGH">High</option>
                                    <option value="CRITICAL">Critical</option>
                                </select>
                            </div>
                            <button type="submit" className="btn-primary w-full flex items-center justify-center gap-2">
                                <TreePine className="w-4 h-4" /> Create Rule
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

import { useState, useEffect } from 'react';
import { analyticsAPI } from '../services/api';
import { BarChart2, Calendar, TreePine, Leaf, Droplets, Thermometer, Wind, Zap } from 'lucide-react';
import { BarChart, Bar, AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
        return (
            <div className="border border-forest-border/30 p-3.5 rounded-xl"
                style={{
                    background: 'linear-gradient(135deg, rgba(15, 33, 15, 0.97), rgba(10, 23, 10, 0.99))',
                    boxShadow: '0 8px 30px rgba(0,0,0,0.5)',
                    backdropFilter: 'blur(12px)',
                }}>
                <p className="text-forest-muted/70 text-xs mb-1 uppercase tracking-wider font-medium">{label}</p>
                {payload.map((p, i) => (
                    <p key={i} className="text-forest-cream text-sm font-bold flex items-center gap-1">
                        <span className="w-2 h-2 rounded-full" style={{ background: p.color }} />
                        {p.value} <span className="text-xs text-forest-muted/50 font-normal">{p.unit || ''}</span>
                    </p>
                ))}
            </div>
        );
    }
    return null;
};

export default function Analytics() {
    const [tab, setTab] = useState('energy');
    const [dateRange, setDateRange] = useState({
        start: new Date(Date.now() - 7 * 86400000).toISOString().split('T')[0],
        end: new Date().toISOString().split('T')[0],
    });
    const [energyData, setEnergyData] = useState([]);
    const [comfortData, setComfortData] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => { fetchData(); }, [dateRange]);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [eRes, cRes] = await Promise.allSettled([
                analyticsAPI.getEnergy(dateRange.start, dateRange.end),
                analyticsAPI.getComfort(dateRange.start, dateRange.end),
            ]);
            if (eRes.status === 'fulfilled') setEnergyData(eRes.value.data || []);
            if (cRes.status === 'fulfilled') setComfortData(cRes.value.data || []);
        } catch { } finally { setLoading(false); }
    };

    const tabs = [
        { key: 'energy', label: 'Energy', icon: Zap, color: 'text-forest-gold', activeColor: 'text-forest-gold', borderColor: 'border-forest-gold' },
        { key: 'temperature', label: 'Temperature', icon: Thermometer, color: 'text-rose-400', activeColor: 'text-rose-400', borderColor: 'border-rose-400' },
        { key: 'humidity', label: 'Humidity', icon: Droplets, color: 'text-blue-400', activeColor: 'text-blue-400', borderColor: 'border-blue-400' },
        { key: 'co2', label: 'COΓéé', icon: Wind, color: 'text-forest-spring', activeColor: 'text-forest-spring', borderColor: 'border-forest-spring' },
    ];

    const activeTab = tabs.find(t => t.key === tab);

    if (loading && !energyData.length && !comfortData.length) return (
        <div className="flex items-center justify-center h-[50vh]">
            <div className="relative">
                <div className="animate-spin rounded-full h-14 w-14 border-t-2 border-b-2 border-forest-spring"></div>
                <TreePine className="w-6 h-6 text-forest-spring absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
        </div>
    );

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex items-center justify-between flex-wrap gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-forest-cream font-display flex items-center gap-3">
                        <BarChart2 className="w-7 h-7 text-forest-spring" />
                        Analytics
                    </h1>
                    <p className="text-sm text-forest-muted mt-1.5">Energy consumption and environmental data trends</p>
                </div>
                <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4 text-forest-muted" />
                    <input type="date" value={dateRange.start} onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                        className="input-scada text-xs py-1.5" />
                    <span className="text-forest-muted/30">ΓåÆ</span>
                    <input type="date" value={dateRange.end} onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                        className="input-scada text-xs py-1.5" />
                </div>
            </div>

            {/* Tabs */}
            <div className="flex items-center gap-6 border-b border-forest-border/20 pb-1">
                {tabs.map(t => {
                    const Icon = t.icon;
                    return (
                        <button key={t.key} onClick={() => setTab(t.key)}
                            className={`flex items-center gap-2 pb-3 px-1 text-sm font-medium border-b-2 transition-all ${tab === t.key
                                ? `${t.activeColor} ${t.borderColor}`
                                : 'text-forest-muted border-transparent hover:text-forest-cream'}`}>
                            <Icon className="w-4 h-4" /> {t.label}
                        </button>
                    );
                })}
            </div>

            {/* Chart */}
            <div className="glass-panel rounded-2xl overflow-hidden">
                <div className="p-6 pb-2 flex items-center justify-between">
                    <h3 className="text-sm font-bold text-forest-muted uppercase tracking-wider flex items-center gap-2">
                        {activeTab && <activeTab.icon className={`w-4 h-4 ${activeTab.color}`} />}
                        {tab === 'energy' ? 'Energy Consumption' : `${activeTab?.label || ''} Trends`}
                    </h3>
                    {loading && <div className="w-4 h-4 border-2 border-forest-spring/30 border-t-forest-spring rounded-full animate-spin" />}
                </div>

                <div className="h-[420px] w-full px-4 pb-6">
                    <ResponsiveContainer width="100%" height="100%">
                        {tab === 'energy' ? (
                            <BarChart data={energyData} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
                                <defs>
                                    <linearGradient id="energyGrad" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#e6b422" stopOpacity={0.8} />
                                        <stop offset="95%" stopColor="#e6b422" stopOpacity={0.15} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" stroke="#254025" vertical={false} opacity={0.3} />
                                <XAxis dataKey="date" stroke="#7aaf7a" fontSize={10} tickLine={false} axisLine={false} />
                                <YAxis stroke="#7aaf7a" fontSize={10} tickLine={false} axisLine={false} />
                                <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(74, 222, 128, 0.04)' }} />
                                <Bar dataKey="value" fill="url(#energyGrad)" radius={[6, 6, 0, 0]} unit=" kWh" />
                            </BarChart>
                        ) : (
                            <AreaChart data={comfortData} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
                                <defs>
                                    <linearGradient id="comfortGrad" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor={tab === 'temperature' ? '#ef4444' : tab === 'humidity' ? '#60a5fa' : '#52b788'} stopOpacity={0.3} />
                                        <stop offset="95%" stopColor={tab === 'temperature' ? '#ef4444' : tab === 'humidity' ? '#60a5fa' : '#52b788'} stopOpacity={0} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" stroke="#254025" vertical={false} opacity={0.3} />
                                <XAxis dataKey="date" stroke="#7aaf7a" fontSize={10} tickLine={false} axisLine={false} />
                                <YAxis stroke="#7aaf7a" fontSize={10} tickLine={false} axisLine={false} />
                                <Tooltip content={<CustomTooltip />} cursor={{ stroke: '#254025', strokeDasharray: '4 4' }} />
                                <Area type="monotone" dataKey="value"
                                    stroke={tab === 'temperature' ? '#ef4444' : tab === 'humidity' ? '#60a5fa' : '#52b788'}
                                    strokeWidth={2.5}
                                    fill="url(#comfortGrad)"
                                    activeDot={{ r: 5, strokeWidth: 0, fill: '#faf5eb' }} />
                            </AreaChart>
                        )}
                    </ResponsiveContainer>
                </div>

                {/* Empty state */}
                {((tab === 'energy' && energyData.length === 0) || (tab !== 'energy' && comfortData.length === 0)) && !loading && (
                    <div className="text-center py-12 -mt-[350px] relative z-10">
                        <span className="text-5xl block mb-3">≡ƒôè</span>
                        <p className="text-forest-muted">No data available for the selected period.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { inventoryAPI, scheduleAPI } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Package, TrendingDown, Plus, Beaker, Leaf, X, TreePine,
    AlertTriangle, CheckCircle, Sparkles, Cpu, Activity, Zap,
    ShieldCheck, Calendar, ArrowUpRight, BarChart3
} from 'lucide-react';

const SummaryCard = ({ title, value, icon: Icon, color, trend }) => (
    <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="glass-card p-6 rounded-[2rem] flex items-center justify-between group relative overflow-hidden"
    >
        <div className="absolute top-0 right-0 w-32 h-32 rounded-full blur-[80px] pointer-events-none opacity-0 group-hover:opacity-40 transition-opacity duration-700"
            style={{ background: color?.includes('emerald') ? 'rgba(82, 183, 136, 0.4)' : color?.includes('amber') ? 'rgba(245, 158, 11, 0.3)' : 'rgba(230, 180, 34, 0.3)' }} />

        <div className="relative z-10">
            <p className="text-[10px] text-forest-muted font-bold uppercase tracking-[0.2em] mb-2">{title}</p>
            <div className="flex items-baseline gap-2">
                <h3 className="text-4xl font-extrabold text-forest-cream font-display tracking-tight">{value}</h3>
                {trend && <span className="text-[10px] font-bold text-emerald-400 flex items-center gap-0.5"><ArrowUpRight className="w-3 h-3" /> {trend}</span>}
            </div>
        </div>

        <div className={`p-4 rounded-2xl border transition-all duration-500 group-hover:scale-110 group-hover:rotate-12 ${color}`}>
            <Icon className="w-7 h-7" />
        </div>
    </motion.div>
);

export default function Antennary() {
    const [tab, setTab] = useState('tasks');
    const [inventory, setInventory] = useState([]);
    const [tasks, setTasks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showAddItem, setShowAddItem] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const [itemForm, setItemForm] = useState({
        name: '', category: 'substrate', quantity: 0, unit: 'kg', min_stock: 5, notes: ''
    });

    const fetchData = async () => {
        try {
            setLoading(true);
            const [invRes, taskRes] = await Promise.allSettled([
                inventoryAPI.getAll(),
                scheduleAPI.getAll()
            ]);
            if (invRes.status === 'fulfilled') {
                const data = invRes.value.data;
                setInventory(Array.isArray(data) ? data : data.items || []);
            }
            if (taskRes.status === 'fulfilled') {
                const data = taskRes.value.data;
                setTasks(Array.isArray(data) ? data : data.tasks || []);
            }
        } catch (err) {
            setError('Failed to establish connection with neural grid');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { fetchData(); }, []);

    const lowStock = inventory.filter(i => i.quantity <= i.min_stock);

    const handleAddItem = async (e) => {
        e.preventDefault();
        try {
            await inventoryAPI.create({
                ...itemForm,
                quantity: parseFloat(itemForm.quantity),
                min_stock: parseFloat(itemForm.min_stock)
            });
            setShowAddItem(false);
            setItemForm({ name: '', category: 'substrate', quantity: 0, unit: 'kg', min_stock: 5, notes: '' });
            setSuccess('Inventory matrix updated successfully ≡ƒî┐');
            fetchData();
        } catch (err) {
            setError(err.response?.data?.detail || 'Matrix write failed');
        }
    };

    const handleToggleTask = async (taskId, completed) => {
        try {
            if (!completed) {
                await scheduleAPI.complete(taskId);
            }
            fetchData();
        } catch (err) {
            setError(err.response?.data?.detail || 'Task synchronization error');
        }
    };

    const catIcon = (category) => {
        const icons = {
            substrate: '≡ƒî╛', chemical: '≡ƒº¬', equipment: 'ΓÜÖ∩╕Å', packaging: '≡ƒôª', culture: '≡ƒº¼'
        };
        return icons[category] || '≡ƒôª';
    };

    if (loading) return (
        <div className="flex flex-col items-center justify-center h-[60vh]">
            <div className="relative mb-6">
                <div className="absolute inset-0 rounded-full border-4 border-forest-spring/10 animate-ping"></div>
                <div className="animate-spin rounded-full h-20 w-20 border-t-2 border-forest-spring"></div>
                <Sparkles className="w-8 h-8 text-forest-spring absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
            <p className="text-forest-muted animate-pulse font-bold tracking-widest text-xs uppercase">Initializing Antigravity Grid</p>
        </div>
    );

    return (
        <div className="space-y-10 page-enter">
            {/* Header / Brand */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2.5 rounded-xl bg-forest-spring/15 border border-forest-spring/20">
                            <Sparkles className="w-6 h-6 text-forest-spring" />
                        </div>
                        <h1 className="text-4xl font-extrabold text-forest-cream font-display tracking-tight">
                            Antigravity <span className="text-emerald-400 font-light italic">Hub</span>
                        </h1>
                    </div>
                    <p className="text-sm text-forest-muted ml-1 flex items-center gap-2">
                        <Activity className="w-3.5 h-3.5" />
                        Autonomous farm management & inventory orchestration
                    </p>
                </div>

                <div className="flex items-center gap-4 bg-forest-darkest/40 p-1.5 rounded-2xl border border-forest-border/20 backdrop-blur-md">
                    <div className="px-4 py-2 rounded-xl flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
                        <span className="text-xs font-bold text-forest-cream uppercase tracking-wider">Neural Link Active</span>
                    </div>
                </div>
            </div>

            {/* Error/Success Notifications */}
            <AnimatePresence>
                {error && (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
                        className="bg-rose-500/10 border border-rose-500/20 text-rose-400 px-6 py-4 rounded-2xl text-sm flex justify-between items-center backdrop-blur-xl">
                        <div className="flex items-center gap-3">
                            <AlertTriangle className="w-5 h-5" />
                            <span className="font-medium">{error}</span>
                        </div>
                        <button onClick={() => setError('')} className="p-1 hover:bg-rose-500/10 rounded-lg transition-colors"><X className="w-4 h-4" /></button>
                    </motion.div>
                )}
                {success && (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
                        className="bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 px-6 py-4 rounded-2xl text-sm flex justify-between items-center backdrop-blur-xl">
                        <div className="flex items-center gap-3">
                            <CheckCircle className="w-5 h-5" />
                            <span className="font-medium">{success}</span>
                        </div>
                        <button onClick={() => setSuccess('')} className="p-1 hover:bg-emerald-500/10 rounded-lg transition-colors"><X className="w-4 h-4" /></button>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* AI Command Section (New Antigravity-specific feature) */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <div className="lg:col-span-3 space-y-8">
                    {/* Summary Matrix */}
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                        <SummaryCard title="Inventory Depth" value={inventory.length} icon={Package} color="text-emerald-400 bg-emerald-500/8 border-emerald-500/12" trend="+12%" />
                        <SummaryCard title="Critical Stock" value={lowStock.length} icon={TrendingDown} color="text-rose-400 bg-rose-500/8 border-rose-500/12" />
                        <SummaryCard title="Active Protocols" value={tasks.filter(t => !t.completed).length} icon={Beaker} color="text-forest-gold bg-forest-gold/8 border-forest-gold/12" trend="Active" />
                    </div>

                    {/* Operational Tabs */}
                    <div className="glass-panel rounded-[2.5rem] p-4 flex items-center gap-2 inline-flex border border-forest-border/20">
                        <button onClick={() => setTab('tasks')}
                            className={`flex items-center gap-2 px-8 py-3 rounded-[1.8rem] text-sm font-bold transition-all duration-300 ${tab === 'tasks'
                                ? 'bg-forest-spring text-forest-darkest shadow-[0_0_25px_rgba(74,222,128,0.3)]'
                                : 'text-forest-muted hover:text-forest-cream'}`}>
                            <Zap className="w-4 h-4" /> Operational Tasks
                        </button>
                        <button onClick={() => setTab('inventory')}
                            className={`flex items-center gap-2 px-8 py-3 rounded-[1.8rem] text-sm font-bold transition-all duration-300 ${tab === 'inventory'
                                ? 'bg-forest-spring text-forest-darkest shadow-[0_0_25px_rgba(74,222,128,0.3)]'
                                : 'text-forest-muted hover:text-forest-cream'}`}>
                            <Package className="w-4 h-4" /> Resource Matrix
                        </button>
                    </div>

                    {tab === 'tasks' ? (
                        <div className="glass-panel rounded-[2.5rem] p-10 relative overflow-hidden">
                            {/* Decorative background logo */}
                            <Sparkles className="absolute -bottom-10 -right-10 w-64 h-64 text-forest-spring/5 rotate-12 pointer-events-none" />

                            <div className="flex justify-between items-center mb-10">
                                <div>
                                    <h2 className="text-2xl font-bold text-forest-cream font-display flex items-center gap-3">
                                        <Calendar className="w-6 h-6 text-forest-spring" /> Current Protocols
                                    </h2>
                                    <p className="text-sm text-forest-muted mt-1">Farm synchronization tasks</p>
                                </div>
                                <div className="text-right">
                                    <span className="text-xs font-bold text-forest-spring uppercase tracking-widest px-4 py-1.5 rounded-full border border-forest-spring/20 bg-forest-spring/5">
                                        Today: {new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                                    </span>
                                </div>
                            </div>

                            {tasks.length === 0 ? (
                                <div className="text-center py-20 bg-forest-darkest/20 rounded-[2rem] border border-forest-border/10">
                                    <div className="w-20 h-20 rounded-full bg-emerald-500/10 flex items-center justify-center mx-auto mb-6">
                                        <CheckCircle className="w-10 h-10 text-emerald-400" />
                                    </div>
                                    <h3 className="text-2xl font-bold text-forest-cream font-display mb-2">Protocols Balanced</h3>
                                    <p className="text-forest-muted text-sm max-w-xs mx-auto">All operational directives have been successfully executed.</p>
                                </div>
                            ) : (
                                <div className="grid gap-4">
                                    {tasks.map(task => (
                                        <motion.div key={task.id}
                                            initial={{ opacity: 0, x: -10 }}
                                            animate={{ opacity: 1, x: 0 }}
                                            className="flex items-center gap-5 p-5 rounded-3xl border border-forest-border/10 hover:border-forest-spring/30 transition-all group relative overflow-hidden"
                                            style={{ background: 'linear-gradient(135deg, rgba(15, 33, 15, 0.4), rgba(10, 23, 10, 0.3))' }}>

                                            <button onClick={() => handleToggleTask(task.id, task.completed)}
                                                className={`p-3 rounded-2xl transition-all duration-500 border ${task.completed ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-forest-darkest/40 text-forest-muted/40 hover:text-forest-cream border-forest-border/20'}`}>
                                                <CheckCircle className="w-6 h-6" />
                                            </button>

                                            <div className="flex-1">
                                                <div className="flex items-center gap-3 mb-1">
                                                    <p className={`text-lg font-bold ${task.completed ? 'text-forest-muted/40 line-through' : 'text-forest-cream'}`}>{task.title}</p>
                                                    {task.priority === 'HIGH' && <span className="px-2 py-0.5 rounded-full bg-rose-500/10 text-rose-400 text-[10px] font-bold uppercase tracking-widest border border-rose-500/20">Critical</span>}
                                                </div>
                                                <div className="flex items-center gap-4 text-xs text-forest-muted/60">
                                                    <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {task.due_date ? new Date(task.due_date).toLocaleDateString() : 'Continuous'}</span>
                                                    <span className="flex items-center gap-1"><Activity className="w-3 h-3" /> {task.completed ? 'Executed' : 'Pending Synchronization'}</span>
                                                </div>
                                            </div>

                                            <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                <ArrowUpRight className="w-5 h-5 text-forest-spring/40" />
                                            </div>
                                        </motion.div>
                                    ))}
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="space-y-6">
                            <div className="flex justify-between items-center">
                                <h2 className="text-2xl font-bold text-forest-cream font-display">Inventory Matrix</h2>
                                <button onClick={() => setShowAddItem(true)} className="btn-primary flex items-center gap-2 text-sm px-6 rounded-2xl">
                                    <Plus className="w-4 h-4" /> Expand Inventory
                                </button>
                            </div>

                            {inventory.length === 0 ? (
                                <div className="glass-panel rounded-[2rem] p-20 text-center border border-forest-border/10">
                                    <Package className="w-20 h-20 text-forest-muted/20 mx-auto mb-6" />
                                    <h3 className="text-2xl font-bold text-forest-cream font-display mb-2">Matrix Empty</h3>
                                    <p className="text-forest-muted text-sm">Initiate the first resource entry to begin tracking.</p>
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {inventory.map(item => (
                                        <motion.div key={item.id}
                                            initial={{ opacity: 0, scale: 0.95 }}
                                            animate={{ opacity: 1, scale: 1 }}
                                            className="glass-card rounded-3xl p-6 flex items-center gap-5 border border-forest-border/15 group hover:border-forest-spring/20">
                                            <div className="w-16 h-16 rounded-2xl bg-forest-darkest/60 flex items-center justify-center text-3xl border border-forest-border/10 group-hover:scale-110 transition-transform">
                                                {catIcon(item.category)}
                                            </div>
                                            <div className="flex-1">
                                                <h3 className="text-lg font-bold text-forest-cream">{item.name}</h3>
                                                <p className="text-xs text-forest-muted/60 uppercase tracking-widest font-bold mt-0.5">{item.category}</p>
                                            </div>
                                            <div className="text-right">
                                                <p className={`text-2xl font-black ${item.quantity <= item.min_stock ? 'text-rose-400' : 'text-emerald-400'}`}>{item.quantity} <span className="text-xs font-normal text-forest-muted/40 uppercase">{item.unit}</span></p>
                                                {item.quantity <= item.min_stock && (
                                                    <span className="text-[10px] font-black text-rose-500 uppercase flex items-center gap-1 justify-end mt-1 animate-pulse">
                                                        <AlertTriangle className="w-3 h-3" /> Replenish
                                                    </span>
                                                )}
                                            </div>
                                        </motion.div>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Sidebar - AI Antigravity Insights */}
                <div className="space-y-8">
                    <div className="glass-panel rounded-[2.5rem] p-8 border-forest-spring/20 relative overflow-hidden bg-gradient-to-br from-forest-spring/5 to-transparent">
                        <div className="absolute top-0 right-0 p-4">
                            <Sparkles className="w-6 h-6 text-forest-spring/40" />
                        </div>

                        <h3 className="text-lg font-bold text-forest-cream mb-6 flex items-center gap-2">
                            <Cpu className="w-5 h-5 text-forest-spring" /> AI Insights
                        </h3>

                        <div className="space-y-6">
                            <div className="p-4 rounded-2xl bg-forest-darkest/40 border border-forest-border/10 space-y-3">
                                <div className="flex items-center gap-2 text-forest-spring">
                                    <Zap className="w-4 h-4" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Prediction</span>
                                </div>
                                <p className="text-xs text-forest-cream leading-relaxed font-medium">
                                    Substrate levels are depleting faster than scheduled. Recommendation: Increase procurement by <span className="text-forest-spring">15%</span> before Friday.
                                </p>
                            </div>

                            <div className="p-4 rounded-2xl bg-forest-darkest/40 border border-forest-border/10 space-y-3">
                                <div className="flex items-center gap-2 text-forest-gold">
                                    <BarChart3 className="w-4 h-4" />
                                    <span className="text-[10px] font-black uppercase tracking-widest">Efficiency</span>
                                </div>
                                <p className="text-xs text-forest-cream leading-relaxed font-medium">
                                    Operational efficiency is currently at <span className="text-forest-gold">94.8%</span>. Protocol completion rate is trending upwards.
                                </p>
                            </div>

                            <div className="pt-4 border-t border-forest-border/10">
                                <div className="flex items-center justify-between text-[11px] mb-4">
                                    <span className="text-forest-muted font-bold tracking-widest uppercase">System Health</span>
                                    <span className="text-emerald-400 font-bold">Optimal</span>
                                </div>
                                <div className="h-1.5 w-full bg-forest-darkest/60 rounded-full overflow-hidden">
                                    <motion.div initial={{ width: 0 }} animate={{ width: '92%' }} className="h-full bg-forest-spring rounded-full" />
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Quick Stats / Environment */}
                    <div className="glass-card rounded-[2.5rem] p-8 border-forest-border/10">
                        <h3 className="text-sm font-bold text-forest-cream uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
                            <ShieldCheck className="w-4 h-4 text-forest-muted" /> Lab Status
                        </h3>
                        <div className="space-y-5">
                            <div className="flex justify-between items-center">
                                <span className="text-xs text-forest-muted font-medium">Sterilization</span>
                                <span className="text-xs font-bold text-emerald-400">Verifed</span>
                            </div>
                            <div className="flex justify-between items-center">
                                <span className="text-xs text-forest-muted font-medium">Access Log</span>
                                <span className="text-xs font-bold text-forest-cream">Admin (0)</span>
                            </div>
                            <div className="flex justify-between items-center">
                                <span className="text-xs text-forest-muted font-medium">Network Latency</span>
                                <span className="text-xs font-bold text-forest-cream">24ms</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal - Modern & Advanced */}
            {showAddItem && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-forest-darkest/90 backdrop-blur-xl transition-all duration-500" onClick={() => setShowAddItem(false)}>
                    <motion.div
                        initial={{ opacity: 0, scale: 0.9, y: 20 }}
                        animate={{ opacity: 1, scale: 1, y: 0 }}
                        className="rounded-[3rem] p-10 max-w-lg w-full border border-forest-spring/20 relative"
                        style={{
                            background: 'linear-gradient(135deg, rgba(10, 23, 10, 0.98), rgba(5, 13, 5, 1))',
                            boxShadow: '0 50px 150px rgba(0,0,0,0.8), 0 0 80px rgba(74, 222, 128, 0.05)',
                        }}
                        onClick={e => e.stopPropagation()}>

                        <div className="absolute top-0 right-0 p-8">
                            <button onClick={() => setShowAddItem(false)} className="text-forest-muted hover:text-forest-cream p-2 hover:bg-forest-card/30 rounded-full transition-all"><X className="w-6 h-6" /></button>
                        </div>

                        <div className="mb-8">
                            <h2 className="text-2xl font-black text-forest-cream font-display flex items-center gap-3">
                                <Package className="w-7 h-7 text-forest-spring" /> Matrix Initiation
                            </h2>
                            <p className="text-sm text-forest-muted mt-1">Register a new resource into the system.</p>
                        </div>

                        <form onSubmit={handleAddItem} className="space-y-6">
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black text-forest-muted uppercase tracking-[0.2em] ml-1">Asset Name</label>
                                <input placeholder="e.g. Premium Rye Substrate" value={itemForm.name} onChange={(e) => setItemForm({ ...itemForm, name: e.target.value })} className="input-scada w-full bg-forest-darkest/60 h-14" required />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black text-forest-muted uppercase tracking-[0.2em] ml-1">Classification</label>
                                    <select value={itemForm.category} onChange={(e) => setItemForm({ ...itemForm, category: e.target.value })} className="input-scada w-full h-14">
                                        <option value="substrate">Substrate</option>
                                        <option value="chemical">Chemical</option>
                                        <option value="equipment">Equipment</option>
                                        <option value="packaging">Packaging</option>
                                        <option value="culture">Culture</option>
                                    </select>
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black text-forest-muted uppercase tracking-[0.2em] ml-1">Metric Unit</label>
                                    <select value={itemForm.unit} onChange={(e) => setItemForm({ ...itemForm, unit: e.target.value })} className="input-scada w-full h-14">
                                        <option value="kg">kilograms (kg)</option>
                                        <option value="g">grams (g)</option>
                                        <option value="L">liters (L)</option>
                                        <option value="mL">milliliters (mL)</option>
                                        <option value="pcs">pieces (pcs)</option>
                                    </select>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black text-forest-muted uppercase tracking-[0.2em] ml-1">Total Quantity</label>
                                    <input type="number" min="0" step="0.1" value={itemForm.quantity} onChange={(e) => setItemForm({ ...itemForm, quantity: e.target.value })} className="input-scada w-full h-14" required />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black text-forest-muted uppercase tracking-[0.2em] ml-1">Lower Threshold</label>
                                    <input type="number" min="0" step="0.1" value={itemForm.min_stock} onChange={(e) => setItemForm({ ...itemForm, min_stock: e.target.value })} className="input-scada w-full h-14" />
                                </div>
                            </div>

                            <button type="submit" className="btn-primary w-full h-16 flex items-center justify-center gap-3 text-lg font-bold rounded-2xl group overflow-hidden relative">
                                <Zap className="w-5 h-5 group-hover:rotate-12 transition-transform" />
                                Confirm Matrix Write
                                <div className="absolute inset-x-0 bottom-0 h-1 bg-white/20" />
                            </button>
                        </form>
                    </motion.div>
                </div>
            )}
        </div>
    );
}

import { useState, useEffect, useMemo } from 'react';
import { farmAPI } from '../services/api';
import {
    Beaker, Syringe, Moon, Sun, Scissors, CheckCircle,
    AlertTriangle, Plus, X, Clock, Activity, ChevronRight, TreePine, Leaf
} from 'lucide-react';

const STAGE_CONFIG = {
    SUBSTRATE_PREP: { label: 'Substrate Prep', icon: Beaker, color: 'text-emerald-400', bg: 'bg-emerald-500/8', border: 'border-emerald-500/12', dayRange: 'Day 0', gradient: '#52b788' },
    INOCULATION: { label: 'Inoculation', icon: Syringe, color: 'text-lime-400', bg: 'bg-lime-500/8', border: 'border-lime-500/12', dayRange: 'Day 1', gradient: '#a3e635' },
    INCUBATION: { label: 'Dark Run', icon: Moon, color: 'text-forest-mist', bg: 'bg-forest-mist/8', border: 'border-forest-mist/12', dayRange: 'Days 2-10', gradient: '#b8d8b8' },
    FRUITING: { label: 'Light Run', icon: Sun, color: 'text-forest-gold', bg: 'bg-forest-gold/8', border: 'border-forest-gold/12', dayRange: 'Days 11-45', gradient: '#e6b422' },
    HARVEST: { label: 'Harvest', icon: Scissors, color: 'text-amber-400', bg: 'bg-amber-500/8', border: 'border-amber-500/12', dayRange: 'Days 45-60', gradient: '#f59e0b' },
    COMPLETED: { label: 'Completed', icon: CheckCircle, color: 'text-green-400', bg: 'bg-green-500/8', border: 'border-green-500/12', dayRange: 'Done', gradient: '#22c55e' },
    FAILED: { label: 'Failed', icon: AlertTriangle, color: 'text-rose-400', bg: 'bg-rose-500/8', border: 'border-rose-500/12', dayRange: 'ΓÇö', gradient: '#ef4444' },
};

const STAGES_ORDER = ['SUBSTRATE_PREP', 'INOCULATION', 'INCUBATION', 'FRUITING', 'HARVEST', 'COMPLETED'];

const ENV_REQS = {
    INCUBATION: [
        { label: 'Temperature', value: '24-26┬░C', icon: '≡ƒîí∩╕Å' },
        { label: 'Humidity', value: '85-95%', icon: '≡ƒÆº' },
        { label: 'Light', value: 'Darkness', icon: '≡ƒîÖ' },
        { label: 'COΓéé', value: 'Natural', icon: '≡ƒî┐' },
    ],
    FRUITING: [
        { label: 'Temperature', value: '18-22┬░C', icon: '≡ƒîí∩╕Å' },
        { label: 'Humidity', value: '90-95%', icon: '≡ƒÆº' },
        { label: 'Light', value: '12h cycle', icon: 'ΓÿÇ∩╕Å' },
        { label: 'COΓéé', value: '<800ppm', icon: '≡ƒìâ' },
    ]
};

export default function BatchMonitor() {
    const [batches, setBatches] = useState([]);
    const [loading, setLoading] = useState(true);
    const [view, setView] = useState('kanban');
    const [showCreate, setShowCreate] = useState(false);
    const [selectedBatch, setSelectedBatch] = useState(null);
    const [error, setError] = useState('');

    const [form, setForm] = useState({ batch_id: '', strain: 'CM-01', substrate: 'Rice', jars_count: 12, notes: '' });

    const fetchBatches = async () => {
        try {
            const res = await farmAPI.getAllBatches();
            const data = res.data;
            setBatches(Array.isArray(data) ? data : data.batches || []);
        } catch { } finally { setLoading(false); }
    };

    useEffect(() => { fetchBatches(); }, []);

    const handleCreate = async (e) => {
        e.preventDefault();
        try {
            await farmAPI.createBatch(form);
            setShowCreate(false);
            setForm({ batch_id: '', strain: 'CM-01', substrate: 'Rice', jars_count: 12, notes: '' });
            fetchBatches();
        } catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    const handleAdvance = async (batchId, nextStage) => {
        try {
            await farmAPI.advanceStage(batchId, nextStage);
            fetchBatches();
            setSelectedBatch(null);
        } catch (err) { setError(err.response?.data?.detail || 'Failed to advance'); }
    };

    const grouped = useMemo(() => {
        const g = {};
        STAGES_ORDER.forEach(s => g[s] = []);
        batches.forEach(b => {
            if (g[b.stage]) g[b.stage].push(b);
        });
        return g;
    }, [batches]);

    const daysSince = (dateStr) => {
        if (!dateStr) return 0;
        return Math.floor((Date.now() - new Date(dateStr).getTime()) / 86400000);
    };

    if (loading) return (
        <div className="flex items-center justify-center h-[50vh]">
            <div className="relative">
                <div className="animate-spin rounded-full h-14 w-14 border-t-2 border-b-2 border-forest-spring"></div>
                <TreePine className="w-6 h-6 text-forest-spring absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
        </div>
    );

    return (
        <div className="space-y-8">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-forest-cream font-display flex items-center gap-3">
                        <Beaker className="w-7 h-7 text-forest-spring" />
                        Batch Monitor
                    </h1>
                    <p className="text-sm text-forest-muted mt-1.5">Track cultivation lifecycle from seed to harvest</p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="flex rounded-xl border border-forest-border/20 p-0.5"
                        style={{ background: 'rgba(5, 13, 5, 0.4)' }}>
                        <button onClick={() => setView('kanban')}
                            className={`px-4 py-2 rounded-lg text-xs font-medium transition-all ${view === 'kanban'
                                ? 'text-emerald-300'
                                : 'text-forest-muted hover:text-forest-cream'}`}
                            style={view === 'kanban' ? { background: 'linear-gradient(135deg, rgba(27, 67, 50, 0.4), rgba(45, 106, 79, 0.2))' } : undefined}>
                            Kanban
                        </button>
                        <button onClick={() => setView('timeline')}
                            className={`px-4 py-2 rounded-lg text-xs font-medium transition-all ${view === 'timeline'
                                ? 'text-emerald-300'
                                : 'text-forest-muted hover:text-forest-cream'}`}
                            style={view === 'timeline' ? { background: 'linear-gradient(135deg, rgba(27, 67, 50, 0.4), rgba(45, 106, 79, 0.2))' } : undefined}>
                            Timeline
                        </button>
                    </div>
                    <button onClick={() => setShowCreate(true)} className="btn-primary flex items-center gap-2 text-sm">
                        <Plus className="w-4 h-4" /> New Batch
                    </button>
                </div>
            </div>

            {error && (
                <div className="bg-red-500/10 border border-red-500/20 text-red-400 px-4 py-3 rounded-xl text-sm flex justify-between items-center">
                    <span>{error}</span>
                    <button onClick={() => setError('')}><X className="w-4 h-4" /></button>
                </div>
            )}

            {/* Kanban View */}
            {view === 'kanban' ? (
                <div className="flex gap-4 overflow-x-auto pb-4">
                    {STAGES_ORDER.map(stage => {
                        const conf = STAGE_CONFIG[stage];
                        const Icon = conf.icon;
                        return (
                            <div key={stage} className="min-w-[260px] flex-1">
                                <div className="flex items-center gap-2 mb-3 px-1">
                                    <Icon className={`w-4 h-4 ${conf.color}`} />
                                    <span className={`text-sm font-semibold ${conf.color}`}>{conf.label}</span>
                                    <span className="ml-auto text-xs text-forest-muted/40 px-2 py-0.5 rounded-full border border-forest-border/10"
                                        style={{ background: 'rgba(26, 58, 26, 0.2)' }}>{grouped[stage].length}</span>
                                </div>
                                <div className="space-y-2">
                                    {grouped[stage].map(batch => (
                                        <div key={batch.id} onClick={() => setSelectedBatch(batch)}
                                            className={`p-4 rounded-xl border ${conf.border} hover:bg-forest-card/30 transition-all cursor-pointer group backdrop-blur-sm`}
                                            style={{ background: 'linear-gradient(145deg, rgba(26, 58, 26, 0.2), rgba(15, 33, 15, 0.15))' }}>
                                            <div className="flex items-center justify-between mb-2">
                                                <span className="text-sm font-bold text-forest-cream">{batch.batch_id}</span>
                                                <ChevronRight className="w-4 h-4 text-forest-muted/30 group-hover:text-forest-cream transition-colors" />
                                            </div>
                                            <p className="text-xs text-forest-muted">≡ƒº¼ {batch.strain}</p>
                                            <div className="flex items-center gap-2 mt-2 text-[11px] text-forest-muted/40">
                                                <Clock className="w-3 h-3" />
                                                <span>Day {daysSince(batch.start_date)}</span>
                                                <span>ΓÇó {batch.jars_count} jars</span>
                                            </div>
                                        </div>
                                    ))}
                                    {grouped[stage].length === 0 && (
                                        <div className="p-8 rounded-xl border border-dashed border-forest-border/10 text-center">
                                            <p className="text-xs text-forest-muted/30">No batches</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            ) : (
                /* Timeline View */
                <div className="glass-panel rounded-2xl p-6">
                    {batches.length === 0 ? (
                        <div className="text-center py-16">
                            <span className="text-6xl block mb-4">≡ƒî▒</span>
                            <h3 className="text-xl font-semibold text-forest-cream font-display mb-2">No Batches Yet</h3>
                            <p className="text-forest-muted text-sm">Create your first cultivation batch to start the journey.</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {batches.map(batch => {
                                const conf = STAGE_CONFIG[batch.stage] || STAGE_CONFIG.SUBSTRATE_PREP;
                                const Icon = conf.icon;
                                const stageIdx = STAGES_ORDER.indexOf(batch.stage);
                                const progress = ((stageIdx + 1) / STAGES_ORDER.length) * 100;
                                return (
                                    <div key={batch.id} onClick={() => setSelectedBatch(batch)}
                                        className="p-5 rounded-2xl border border-forest-border/12 hover:bg-forest-card/15 transition-all cursor-pointer group"
                                        style={{ background: 'linear-gradient(145deg, rgba(15, 33, 15, 0.2), rgba(10, 23, 10, 0.15))' }}>
                                        <div className="flex items-center justify-between mb-3">
                                            <div className="flex items-center gap-3">
                                                <div className={`p-2 rounded-lg ${conf.bg} ${conf.border} border`}>
                                                    <Icon className={`w-4 h-4 ${conf.color}`} />
                                                </div>
                                                <div>
                                                    <p className="font-bold text-forest-cream">{batch.batch_id}</p>
                                                    <p className="text-xs text-forest-muted">≡ƒº¼ {batch.strain} ΓÇó {batch.substrate}</p>
                                                </div>
                                            </div>
                                            <span className={`text-xs px-3 py-1 rounded-full ${conf.bg} ${conf.color} border ${conf.border} font-medium`}>{conf.label}</span>
                                        </div>
                                        <div className="w-full h-2 rounded-full overflow-hidden"
                                            style={{ background: 'rgba(5, 13, 5, 0.5)' }}>
                                            <div className="h-full rounded-full transition-all duration-700"
                                                style={{
                                                    width: `${progress}%`,
                                                    background: `linear-gradient(90deg, #1b4332, ${conf.gradient})`,
                                                }} />
                                        </div>
                                        <div className="flex justify-between mt-2 text-[11px] text-forest-muted/40">
                                            <span>Day {daysSince(batch.start_date)}</span>
                                            <span>{Math.round(progress)}% complete</span>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            )}

            {/* Create Batch Modal */}
            {showCreate && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-forest-darkest/85 backdrop-blur-md" onClick={() => setShowCreate(false)}>
                    <div className="rounded-3xl p-8 max-w-lg w-full border border-forest-border/25 page-enter"
                        style={{
                            background: 'linear-gradient(135deg, rgba(19, 42, 19, 0.97), rgba(10, 23, 10, 0.99))',
                            boxShadow: '0 30px 100px rgba(0,0,0,0.6), 0 0 60px rgba(74, 222, 128, 0.04)',
                        }}
                        onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-xl font-bold text-forest-cream font-display flex items-center gap-2">
                                <Leaf className="w-5 h-5 text-forest-spring" /> New Cultivation Batch
                            </h2>
                            <button onClick={() => setShowCreate(false)} className="text-forest-muted hover:text-forest-cream p-1"><X className="w-5 h-5" /></button>
                        </div>
                        <form onSubmit={handleCreate} className="space-y-4">
                            <div>
                                <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Batch ID</label>
                                <input value={form.batch_id} onChange={(e) => setForm({ ...form, batch_id: e.target.value })} className="input-scada w-full" required placeholder="e.g. CM-2026-001" />
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Strain</label>
                                    <select value={form.strain} onChange={(e) => setForm({ ...form, strain: e.target.value })} className="input-scada w-full">
                                        <option value="CM-01">CM-01 (Standard)</option>
                                        <option value="CM-02">CM-02 (High Potency)</option>
                                        <option value="CM-03">CM-03 (Premium)</option>
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Substrate</label>
                                    <select value={form.substrate} onChange={(e) => setForm({ ...form, substrate: e.target.value })} className="input-scada w-full">
                                        <option value="Rice">Rice</option>
                                        <option value="Brown Rice">Brown Rice</option>
                                        <option value="Wheat">Wheat</option>
                                    </select>
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Jars Count</label>
                                <input type="number" min="1" value={form.jars_count} onChange={(e) => setForm({ ...form, jars_count: parseInt(e.target.value) || 1 })} className="input-scada w-full" />
                            </div>
                            <div>
                                <label className="block text-xs text-forest-muted uppercase tracking-wider mb-1.5 font-medium">Notes (optional)</label>
                                <textarea value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} className="input-scada w-full resize-none" rows={3} />
                            </div>
                            <button type="submit" className="btn-primary w-full flex items-center justify-center gap-2">
                                <TreePine className="w-4 h-4" /> Create Batch
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Batch Detail Modal */}
            {selectedBatch && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-forest-darkest/85 backdrop-blur-md" onClick={() => setSelectedBatch(null)}>
                    <div className="rounded-3xl p-8 max-w-2xl w-full border border-forest-border/25 max-h-[85vh] overflow-y-auto page-enter"
                        style={{
                            background: 'linear-gradient(135deg, rgba(19, 42, 19, 0.97), rgba(10, 23, 10, 0.99))',
                            boxShadow: '0 30px 100px rgba(0,0,0,0.6), 0 0 60px rgba(74, 222, 128, 0.04)',
                        }}
                        onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-start mb-6">
                            <div>
                                <h2 className="text-2xl font-bold text-forest-cream font-display">{selectedBatch.batch_id}</h2>
                                <p className="text-sm text-forest-muted mt-1">≡ƒº¼ {selectedBatch.strain} ΓÇó {selectedBatch.substrate} ΓÇó {selectedBatch.jars_count} jars</p>
                            </div>
                            <button onClick={() => setSelectedBatch(null)} className="text-forest-muted hover:text-forest-cream p-1"><X className="w-5 h-5" /></button>
                        </div>

                        {/* Stage Progress */}
                        <div className="mb-6">
                            <div className="flex items-center gap-1">
                                {STAGES_ORDER.map((stage, i) => {
                                    const conf = STAGE_CONFIG[stage];
                                    const isActive = stage === selectedBatch.stage;
                                    const isPast = STAGES_ORDER.indexOf(selectedBatch.stage) > i;
                                    return (
                                        <div key={stage} className="flex-1">
                                            <div className={`h-2 rounded-full transition-all ${isPast ? 'bg-emerald-500' : isActive ? 'bg-emerald-400 animate-pulse' : ''}`}
                                                style={!isPast && !isActive ? { background: 'rgba(5, 13, 5, 0.5)' } : undefined} />
                                            <p className={`text-[10px] mt-1 text-center ${isActive ? conf.color + ' font-bold' : 'text-forest-muted/30'}`}>{conf.label}</p>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Environmental Requirements */}
                        {ENV_REQS[selectedBatch.stage] && (
                            <div className="mb-6">
                                <h3 className="text-sm font-semibold text-forest-cream mb-3 flex items-center gap-2"><Leaf className="w-4 h-4 text-emerald-400" /> Optimal Conditions</h3>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                    {ENV_REQS[selectedBatch.stage].map((req, i) => (
                                        <div key={i} className="p-4 rounded-xl border border-forest-border/12 text-center"
                                            style={{ background: 'linear-gradient(135deg, rgba(15, 33, 15, 0.3), rgba(10, 23, 10, 0.2))' }}>
                                            <span className="text-lg block mb-1">{req.icon}</span>
                                            <p className="text-xs text-forest-muted">{req.label}</p>
                                            <p className="text-sm font-bold text-forest-cream mt-0.5">{req.value}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Notes */}
                        {selectedBatch.notes && (
                            <div className="mb-6 p-4 rounded-xl border border-forest-border/12"
                                style={{ background: 'linear-gradient(135deg, rgba(26, 58, 26, 0.15), rgba(19, 42, 19, 0.1))' }}>
                                <p className="text-xs text-forest-muted uppercase tracking-wider mb-1 font-medium">Notes</p>
                                <p className="text-sm text-forest-mist/80">{selectedBatch.notes}</p>
                            </div>
                        )}

                        {/* Advance Button */}
                        {selectedBatch.stage !== 'COMPLETED' && selectedBatch.stage !== 'FAILED' && (
                            <button
                                onClick={() => {
                                    const idx = STAGES_ORDER.indexOf(selectedBatch.stage);
                                    if (idx < STAGES_ORDER.length - 1) handleAdvance(selectedBatch.id, STAGES_ORDER[idx + 1]);
                                }}
                                className="w-full py-3.5 rounded-xl font-semibold text-white transition-all active:scale-[0.98] flex items-center justify-center gap-2"
                                style={{
                                    background: 'linear-gradient(135deg, #1b4332, #2d6a4f, #40916c)',
                                    boxShadow: '0 4px 25px rgba(74, 222, 128, 0.2), inset 0 1px 0 rgba(255,255,255,0.1)',
                                }}>
                                <TreePine className="w-4 h-4" /> Advance to Next Stage ΓåÆ
                            </button>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}

import { useState, useEffect } from 'react';
import { buildingAPI } from '../services/api';
import { Building, Plus, Pencil, Trash2, X, MapPin, Layers, TreePine, Leaf } from 'lucide-react';

export default function Buildings() {
    const [buildings, setBuildings] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [editing, setEditing] = useState(null);
    const [error, setError] = useState('');
    const [form, setForm] = useState({ name: '', address: '', floors: 1, description: '' });

    const fetchBuildings = async () => {
        try {
            const res = await buildingAPI.getAll();
            setBuildings(res.data);
        } catch { } finally { setLoading(false); }
    };

    useEffect(() => { fetchBuildings(); }, []);

    const openCreate = () => {
        setForm({ name: '', address: '', floors: 1, description: '' });
        setEditing(null);
        setShowForm(true);
    };

    const openEdit = (b) => {
        setForm({ name: b.name, address: b.address, floors: b.floors, description: b.description || '' });
        setEditing(b);
        setShowForm(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            if (editing) {
                await buildingAPI.update(editing.id, form);
            } else {
                await buildingAPI.create(form);
            }
            setShowForm(false);
            fetchBuildings();
        } catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    const handleDelete = async (id) => {
        if (!confirm('Delete this building?')) return;
        try { await buildingAPI.delete(id); fetchBuildings(); }
        catch (err) { setError(err.response?.data?.detail || 'Failed'); }
    };

    if (loading) return (
        <div className="flex items-center justify-center h-[50vh]">
            <div className="relative">
                <div className="animate-spin rounded-full h-14 w-14 border-t-2 border-b-2 border-forest-spring"></div>
                <TreePine className="w-6 h-6 text-forest-spring absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
            </div>
        </div>
    );

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold text-forest-cream font-display flex items-center gap-3">
